import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type AnalyticsDashboardProps = Record<string, any>;

const DonutSegment: React.FC<{
  size: number;
  radius: number;
  strokeWidth: number;
  percentage: number;
  color: string;
  rotation: number;
  progress: number;
}> = ({ size, radius, strokeWidth, percentage, color, rotation, progress }) => {
  const circumference = 2 * Math.PI * radius;
  const targetLength = circumference * percentage;
  const currentLength = targetLength * progress;
  const center = size / 2;

  return (
    <circle
      cx={center}
      cy={center}
      r={radius}
      fill="transparent"
      stroke={color}
      strokeWidth={strokeWidth}
      strokeDasharray={`${currentLength} ${circumference}`}
      strokeLinecap="round"
      style={{
        transformOrigin: `${center}px ${center}px`,
        transform: `rotate(${rotation}deg)`,
        transition: "none",
      }}
    />
  );
};

